package com.fifotech.task.controller;
import com.fifotech.task.dto.ApiDtos.*;import com.fifotech.task.service.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final UserService users;public AuthController(AuthService auth,UserService users){this.auth=auth;this.users=users;}@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}@PostMapping("/register") @PreAuthorize("hasRole('ADMIN')") public UserResponse register(@Valid @RequestBody UserRequest r){return users.create(r);}}
